1	// Package contractsentinel implements audit rule evaluation over contract artifacts.
2	package contractsentinel
3	
4	import "sort"
5	
6	// Artifact is one compiled contract target under audit.
7	type Artifact struct {
8		Name     string
9		ABI      string
10		Bytecode string
11		Source   string
12	}
13	
14	// Finding is one rule violation with the invariant it breaks.
15	type Finding struct {
16		Rule      string
17		Severity  string
18		Invariant string
19		Evidence  string
20	}
21	
22	// Rule is a static or symbolic check the pipeline can run.
23	type Rule struct {
24		ID          string
25		Kind        string
26		Severity    string
27		Invariant   string
28		RequiresABI bool
29	}
30	
31	// Run executes the deterministic subset of rules and refuses inputs they need.
32	func Run(artifact Artifact, rules []Rule, invariants map[string]bool) ([]Finding, error) {
33		if artifact.Name == "" {
34			return nil, errInvalid("artifact name is required")
35		}
36		var findings []Finding
37		for _, rule := range rules {
38			if rule.RequiresABI && artifact.ABI == "" {
39				return nil, errInvalid("rule " + rule.ID + " needs an ABI")
40			}
41			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
42				return nil, errInvalid("symbolic rule " + rule.ID + " needs bytecode")
43			}
44			if holds, checked := invariants[rule.Invariant]; checked && !holds {
45				findings = append(findings, Finding{Rule: rule.ID, Severity: rule.Severity,
46					Invariant: rule.Invariant, Evidence: "invariant " + rule.Invariant + " does not hold"})
47			}
48		}
49		sort.Slice(findings, func(i, j int) bool {
50			if findings[i].Severity == findings[j].Severity {
51				return findings[i].Rule < findings[j].Rule
52			}
53			return findings[i].Severity > findings[j].Severity
54		})
55		return findings, nil
56	}
57	
58	type errInvalid string
59	
60	func (e errInvalid) Error() string { return string(e) }
