834	// requestJSON mirrors Request but keeps method and target raw, so a valid
835	// JSON document whose fields merely have the wrong JSON type is reported on
836	// the offending field instead of as a generic JSON decode error.
837	type requestJSON struct {
838		Method json.RawMessage `json:"method"`
839		Target json.RawMessage `json:"target"`
840	}
841	
842	// ParseRequest parses and validates one JSON request. Three failure shapes are
843	// kept apart: a document whose JSON syntax is broken fails as a parse failure
844	// without guessing a field; a syntactically valid non-object document (array,
845	// number, string, boolean or null) must be a JSON object; a valid object whose
846	// method or target is not a string fails on that field, naming the JSON type
847	// actually received (null counts as a type error, never as a missing field).
848	// method is always checked before target, regardless of the key order in the
849	// object. Only after both fields are present strings are their contents
850	// (required method, legal token, absolute target without a fragment or a bad
851	// percent escape) validated, so an empty string stays a content error.
852	func ParseRequest(data []byte) (*Request, *Failure) {
853		body, err := unmarshalJSONValue(data)
854		if err != nil {
855			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
856		}
857		if f := requireJSONObject(body, "invalid_request", "request", false); f != nil {
858			return nil, f
859		}
860	
861		var rj requestJSON
862		if err := json.Unmarshal(body, &rj); err != nil {
863			// The document already parsed as one JSON value and starts with '{';
864			// keep this as a parse failure rather than a field error if the object
865			// itself cannot be read.
866			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
867		}
868	
869		var req Request
870		// method is always checked before target, regardless of the key order in
871		// the object; the absent/null/non-string distinction is the shared
872		// decodeStringField, so only the request wording is added here.
873		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
874			return nil, f
875		}
876		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
877			return nil, f
878		}
879	
880		switch {
881		case req.Method == "":
882			return nil, failuref("invalid_request", "method is required")
883		case !isToken(req.Method):
884			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
885		}
886		switch {
887		case req.Target == "" || req.Target[0] != '/':
888			return nil, failuref("invalid_request", "target must start with /")
889		case strings.Contains(req.Target, "#"):
890			return nil, failuref("invalid_request", "target must not contain a fragment")
891		case !validPercentEscapes(req.Target):
892			return nil, failuref("invalid_request", "target contains an invalid percent escape")
893		}
894		return &req, nil
895	}
896	
897	// decodeRequestStringField renders the request wording for one string field;
898	// the absent/null/non-string decision itself is the shared
899	// decodeStringField. An absent field (no such key) is left as the zero value
900	// so the later content checks keep their "field is required" behavior; null
901	// or any non-string JSON value is a type error that names the field and the
902	// JSON type that was actually supplied.
903	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
904		if !decodeStringField(raw, dst) {
905			return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
906		}
907		return nil
908	}
909	
910	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
911	// terms the request error reasons use: "null", "a boolean", "a number",
912	// "a string", "an array" or "an object".
913	func jsonTypeName(raw json.RawMessage) string {
914		switch bytes.TrimSpace(raw)[0] {
915		case 'n':
916			return "null"
917		case 't', 'f':
918			return "a boolean"
919		case '"':
920			return "a string"
921		case '[':
922			return "an array"
923		case '{':
924			return "an object"
925		default:
926			return "a number"
927		}
928	}
