func TestConfigMarshalRulesFieldShape(t *testing.T) {
	// Every rule re-reads with exactly the fields the input grammar allows.
	cfg := mustConfig(t, `{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h",
	  "queryTransforms":[
	    {"op":"set","name":"a","value":""},
