			}
		})
	}
}

func TestResolveJunctionSlashCollapse(t *testing.T) {
	// Only the run where the base path's trailing slashes meet the
	// remainder's leading slashes is collapsed to a single slash; slashes,
	// dot segments and percent escapes anywhere else stay byte for byte.
	cfg := mustConfig(t, `{
	  "routes": [
	    {"id": "multi", "methods": ["GET"], "pathPrefix": "/api",  "upstream": "http://backend.internal/base///"},
	    {"id": "plain", "methods": ["GET"], "pathPrefix": "/v",    "upstream": "http://plain.internal/base"},
	    {"id": "nobase","methods": ["GET"], "pathPrefix": "/n",    "upstream": "http://nb.internal:8080"},
	    {"id": "root",  "methods": ["*"],   "pathPrefix": "/",     "upstream": "https://fallback.internal/base//"}
	  ]
	}`)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "multi-slash base and remainder collapse at the junction",
			request:  `{"method":"GET","target":"/api//orders/7?a=1&a=&x=%2f+"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/orders/7?a=1&a=&x=%2f+",
		},
		{
			name:     "exact prefix with multi-slash base keeps one trailing slash",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/",
		},
		{
			name:     "remainder made only of slashes ends in the one junction slash",
			request:  `{"method":"GET","target":"/api///"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/",
		},
		{
			name:     "internal slashes and dot segments are left untouched",
			request:  `{"method":"GET","target":"/api//a//b/../c/"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/a//b/../c/",
		},
		{
			name:     "encoded slash right at the junction is data, not a junction slash",
			request:  `{"method":"GET","target":"/api/%2f/x"}`,
			routeID:  "multi",
			upstream: "http://backend.internal/base/%2f/x",
		},
		{
			name:     "plain base with doubled leading remainder slashes collapses too",
			request:  `{"method":"GET","target":"/v//orders"}`,
			routeID:  "plain",
			upstream: "http://plain.internal/base/orders",
		},
		{
			name:     "upstream without a base path still joins with one slash",
			request:  `{"method":"GET","target":"/n//orders"}`,
			routeID:  "nobase",
			upstream: "http://nb.internal:8080/orders",
		},
		{
			name:     "upstream without a base path and exact prefix keeps the slash",
			request:  `{"method":"GET","target":"/n"}`,
			routeID:  "nobase",
			upstream: "http://nb.internal:8080/",
		},
		{
			name:     "root request keeps one junction slash over a multi-slash base",
			request:  `{"method":"GET","target":"/"}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/",
		},
		{
			name:     "root request leading multiple slashes follows the junction rule",
			request:  `{"method":"GET","target":"///healthz//"}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/healthz//",
		},
		{
			name:     "root internal slashes and dot segments are preserved",
			request:  `{"method":"GET","target":"/a//b/./c?z=1&&w="}`,
			routeID:  "root",
			upstream: "https://fallback.internal/base/a//b/./c?z=1&&w=",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := resolveJSON(t, cfg, tc.request)
			if res.RouteID != tc.routeID {
				t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
			}
			if res.UpstreamURL != tc.upstream {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
			}
		})
	}
}

func TestResolveEncodedBasePathJoin(t *testing.T) {
	// The upstream base path is sliced out of the raw configured URL and the
	// remainder is appended with exactly one slash at the junction. Encoded
	// slashes (both cases), the userinfo encoding, the IPv6 brackets and the
	// port are content that must survive byte for byte; only the run where
	// the base path's trailing slashes meet the remainder's leading slashes
	// collapses. None of these routes defines queryTransforms, so the raw
	// query is preserved verbatim.
	cfg := mustConfig(t, `{
	  "routes": [
	    {"id": "enc",  "methods": ["GET"], "pathPrefix": "/api", "upstream": "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f///"},
	    {"id": "dots", "methods": ["GET"], "pathPrefix": "/d",   "upstream": "http://dots.internal/a/./b/../c//"},
	    {"id": "root", "methods": ["*"],   "pathPrefix": "/",    "upstream": "https://root.internal/v%2f//base%2f///"}
	  ]
	}`)

	cases := []struct {
		name     string
		request  string
		routeID  string
		upstream string
	}{
		{
			name:     "encoded base path, userinfo, IPv6 and port survive the join",
			request:  `{"method":"GET","target":"/api//%2F/x//y/?a=1&a=&flag"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/%2F/x//y/?a=1&a=&flag",
		},
		{
			name:     "exact prefix keeps the encoded base path and one junction slash",
			request:  `{"method":"GET","target":"/api"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/",
		},
		{
			name:     "exact prefix with empty query keeps the bare question mark",
			request:  `{"method":"GET","target":"/api?"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/?",
		},
		{
			name:     "no query string stays distinct from an empty one",
			request:  `{"method":"GET","target":"/api/x"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/x",
		},
		{
			name:     "duplicate, empty and valueless parameters stay as written",
			request:  `{"method":"GET","target":"/api/p?b=1&b=&flag&b=2&c=%2f"}`,
			routeID:  "enc",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f//base%2f/p?b=1&b=&flag&b=2&c=%2f",
		},
		{
			name:     "root prefix with root target keeps encoded base and junction slash",
			request:  `{"method":"GET","target":"/"}`,
			routeID:  "root",
			upstream: "https://root.internal/v%2f//base%2f/",
		},
		{
			name:     "dot segments in the base path are never resolved",
			request:  `{"method":"GET","target":"/d/x"}`,
			routeID:  "dots",
			upstream: "http://dots.internal/a/./b/../c/x",
		},
		{
			name:     "exact prefix on a dot-segment base keeps the trailing junction slash",
			request:  `{"method":"GET","target":"/d"}`,
			routeID:  "dots",
			upstream: "http://dots.internal/a/./b/../c/",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			res := resolveJSON(t, cfg, tc.request)
			if res.RouteID != tc.routeID {
				t.Errorf("routeId = %q, want %q", res.RouteID, tc.routeID)
			}
			if res.UpstreamURL != tc.upstream {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.upstream)
			}
		})
	}
