	for _, up := range []string{"http://2001:db8::1/base", "http://::1:8080/base", "http://::ffff:192.0.2.1/base"} {
		src := `{"routes":[
		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
