				t.Fatalf("legal JSON must not be called a syntax failure: %q", f.Reason)
			}
		})
	}

	// Genuinely broken syntax stays a parse failure with no field guessed.
	for _, src := range []string{`{bad`, `{"method":`, `{"method":"GET","target":"/api"`} {
